import { composeContext, type CoreContext, type ExtraContext } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const core: CoreContext = { region: 'ap-south', attempt: 3 };
const extras: Record<string, unknown> = {
  region: 'wrong-region',
  attempt: 99,
  traceId: 'trace-1',
  enabled: false,
  nullable: null,
};
const coreBefore = JSON.stringify(core);
const extrasBefore = JSON.stringify(extras);
const result = composeContext(core, extras);
equal(result.region, 'ap-south', 'core region is reserved');
equal(result.attempt, 3, 'core attempt is reserved');
equal(result.traceId, 'trace-1', 'extra string retained');
equal(result.enabled, false, 'extra false retained');
equal(result.nullable, null, 'extra null retained');
equal(JSON.stringify(core), coreBefore, 'core not mutated');
equal(JSON.stringify(extras), extrasBefore, 'extras not mutated');

core.region = 'changed';
core.attempt = 4;
extras.traceId = 'changed';
delete extras.enabled;
extras.addedLater = true;
equal(result.region, 'ap-south', 'later core assignment does not affect result');
equal(result.attempt, 3, 'later reserved assignment does not affect result');
equal(result.traceId, 'trace-1', 'later extra assignment does not affect result');
equal(result.enabled, false, 'later extra deletion does not affect result');
assert(!Object.prototype.hasOwnProperty.call(result, 'addedLater'), 'later extra addition does not affect result');

const inherited = { inherited: 'exclude' };
const ownExtras = Object.create(inherited) as Record<string, unknown>;
ownExtras.own = 'include';
Object.defineProperty(ownExtras, 'hidden', { value: 'exclude', enumerable: false });
const ownResult = composeContext({ region: 'r', attempt: 0 }, ownExtras as ExtraContext);
equal(ownResult.own, 'include', 'own enumerable property included');
assert(!Object.prototype.hasOwnProperty.call(ownResult, 'inherited'), 'inherited property excluded');
assert(!Object.prototype.hasOwnProperty.call(ownResult, 'hidden'), 'non-enumerable property excluded');

const empty = composeContext({ region: '', attempt: 0 }, {});
equal(Object.keys(empty).sort().join(','), 'attempt,region', 'empty extras are valid');

